/**
 * @suppress
 */
public object FfiConverterTypeBatteryMonitor: FfiConverter<BatteryMonitor, Long> {
    override fun lower(value: BatteryMonitor): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): BatteryMonitor {
        return BatteryMonitor(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): BatteryMonitor {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: BatteryMonitor) = 8UL

    override fun write(value: BatteryMonitor, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


