     */
    suspend fun `loadEncryptedPlaces`(`places`: List<EncryptedPlace>): kotlin.UInt
    
    /**
     * Add a user to monitor for boundary crossings
     *
     * The user must be in a shared circle so their location can be decrypted.
     */
    suspend fun `monitorUser`(`userId`: kotlin.String, `circleId`: kotlin.String)
    
    /**
     * Total places loaded across all circles
     */
    suspend fun `placeCount`(): kotlin.UInt
    
