    override suspend fun `checkOwnLocation`(`lat`: kotlin.Double, `lng`: kotlin.Double, `accuracyMeters`: kotlin.Double?) : List<BoundaryCrossing> {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_pingolin_mobile_fn_method_boundarymonitor_check_own_location(
