     * Create a batcher configured for maximum privacy
     */ fun `maximumPrivacy`(): LocationBatcher {
            return FfiConverterTypeLocationBatcher.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_pingolin_mobile_fn_constructor_locationbatcher_maximum_privacy(
    
        _status)
}
    )
    }
    

        
    /**
     * Create a batcher with default privacy config
     */ fun `withDefaults`(): LocationBatcher {
            return FfiConverterTypeLocationBatcher.lift(
