/**
 * @suppress
 */
public object FfiConverterTypeLocationBatcher: FfiConverter<LocationBatcher, Long> {
    override fun lower(value: LocationBatcher): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): LocationBatcher {
        return LocationBatcher(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): LocationBatcher {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: LocationBatcher) = 8UL

    override fun write(value: LocationBatcher, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


