public object FfiConverterTypeTileGeocoder: FfiConverter<TileGeocoder, Long> {
    override fun lower(value: TileGeocoder): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): TileGeocoder {
        return TileGeocoder(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): TileGeocoder {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TileGeocoder) = 8UL

    override fun write(value: TileGeocoder, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



