/**
 * How the client should collect credentials / data for the provider.
 */
sealed class AuthMethod {
    
    /**
     * Plain file picker. `mime_types` constrains the picker.
     */
    data class FileUpload(
        val `mimeTypes`: List<kotlin.String>) : AuthMethod()
        
    {
        

        companion object
    }
    
    /**
     * Deep-link to an external export tool (e.g. Google Takeout)
     * then fall back to a file picker on return.
     */
    data class TakeoutLink(
        val `externalUrl`: kotlin.String, 
        val `mimeTypes`: List<kotlin.String>) : AuthMethod()
        
    {
        

        companion object
    }
    
    /**
     * OAuth 2.0 authorization-code flow with PKCE — safe for public
     * clients (no shipped secret).
     */
    data class OAuth2Pkce(
        val v1: OAuthConfig) : AuthMethod()
        
    {
        

        companion object
    }
    
    /**
     * Username + password / API token entered into a credential form.
     * `fields` is the ordered list of inputs to show.
     */
    data class Credentials(
        val `fields`: List<CredentialField>) : AuthMethod()
        
    {
        

        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAuthMethod : FfiConverterRustBuffer<AuthMethod>{
    override fun read(buf: ByteBuffer): AuthMethod {
        return when(buf.getInt()) {
            1 -> AuthMethod.FileUpload(
                FfiConverterSequenceString.read(buf),
                )
            2 -> AuthMethod.TakeoutLink(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            3 -> AuthMethod.OAuth2Pkce(
                FfiConverterTypeOAuthConfig.read(buf),
                )
            4 -> AuthMethod.Credentials(
                FfiConverterSequenceTypeCredentialField.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthMethod) = when(value) {
        is AuthMethod.FileUpload -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`mimeTypes`)
            )
        }
        is AuthMethod.TakeoutLink -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`externalUrl`)
                + FfiConverterSequenceString.allocationSize(value.`mimeTypes`)
            )
        }
        is AuthMethod.OAuth2Pkce -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeOAuthConfig.allocationSize(value.v1)
            )
        }
        is AuthMethod.Credentials -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeCredentialField.allocationSize(value.`fields`)
            )
        }
    }

    override fun write(value: AuthMethod, buf: ByteBuffer) {
        when(value) {
            is AuthMethod.FileUpload -> {
                buf.putInt(1)
                FfiConverterSequenceString.write(value.`mimeTypes`, buf)
                Unit
            }
            is AuthMethod.TakeoutLink -> {
                buf.putInt(2)
                FfiConverterString.write(value.`externalUrl`, buf)
                FfiConverterSequenceString.write(value.`mimeTypes`, buf)
                Unit
            }
            is AuthMethod.OAuth2Pkce -> {
                buf.putInt(3)
                FfiConverterTypeOAuthConfig.write(value.v1, buf)
                Unit
            }
            is AuthMethod.Credentials -> {
                buf.putInt(4)
                FfiConverterSequenceTypeCredentialField.write(value.`fields`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





