sealed class MobileException(message: String): kotlin.Exception(message) {
        
        class CryptoException(message: String) : MobileException(message)
        
        class KeyNotFound(message: String) : MobileException(message)
        
        class InvalidKey(message: String) : MobileException(message)
        
        class EncryptionFailed(message: String) : MobileException(message)
        
        class DecryptionFailed(message: String) : MobileException(message)
        
        class SerializationException(message: String) : MobileException(message)
        
        class NetworkException(message: String) : MobileException(message)
        
        class InvalidInput(message: String) : MobileException(message)
        
        class StorageException(message: String) : MobileException(message)
        
        class SessionKeyNotFound(message: String) : MobileException(message)
        
        class SignatureInvalid(message: String) : MobileException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileException = FfiConverterTypeMobileError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileError : FfiConverterRustBuffer<MobileException> {
    override fun read(buf: ByteBuffer): MobileException {
        
            return when(buf.getInt()) {
            1 -> MobileException.CryptoException(FfiConverterString.read(buf))
            2 -> MobileException.KeyNotFound(FfiConverterString.read(buf))
            3 -> MobileException.InvalidKey(FfiConverterString.read(buf))
            4 -> MobileException.EncryptionFailed(FfiConverterString.read(buf))
            5 -> MobileException.DecryptionFailed(FfiConverterString.read(buf))
            6 -> MobileException.SerializationException(FfiConverterString.read(buf))
            7 -> MobileException.NetworkException(FfiConverterString.read(buf))
            8 -> MobileException.InvalidInput(FfiConverterString.read(buf))
            9 -> MobileException.StorageException(FfiConverterString.read(buf))
            10 -> MobileException.SessionKeyNotFound(FfiConverterString.read(buf))
            11 -> MobileException.SignatureInvalid(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: MobileException): ULong {
        return 4UL
    }

    override fun write(value: MobileException, buf: ByteBuffer) {
        when(value) {
            is MobileException.CryptoException -> {
                buf.putInt(1)
                Unit
            }
            is MobileException.KeyNotFound -> {
                buf.putInt(2)
                Unit
            }
            is MobileException.InvalidKey -> {
                buf.putInt(3)
                Unit
            }
            is MobileException.EncryptionFailed -> {
                buf.putInt(4)
                Unit
            }
            is MobileException.DecryptionFailed -> {
                buf.putInt(5)
                Unit
            }
            is MobileException.SerializationException -> {
                buf.putInt(6)
                Unit
            }
            is MobileException.NetworkException -> {
                buf.putInt(7)
                Unit
            }
            is MobileException.InvalidInput -> {
                buf.putInt(8)
                Unit
            }
            is MobileException.StorageException -> {
                buf.putInt(9)
                Unit
            }
            is MobileException.SessionKeyNotFound -> {
                buf.putInt(10)
                Unit
            }
            is MobileException.SignatureInvalid -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



